export const BIG: number[];
export const SMALL: number[];
export const TARGET_MIN: number;
export const TARGET_MAX: number;
export const DAILY_SECONDS: number;
export const DAILY_GRACE_SECONDS: number;
export type Op = '+' | '-' | 'x' | '/';
export const OP_SYMBOL: Record<Op, string>;
export type Puzzle = { numbers: number[]; target: number };
export type Step = { a: number; op: Op; b: number; ms: number };
export function apply(a: number, op: Op, b: number): number | null;
export function reachable(numbers: number[]): Map<number, string>;
export function bestSolution(numbers: number[], target: number): { value: number; distance: number; expression: string } | null;
export function makePuzzle(big?: number | 'mix', rand?: () => number): Puzzle;
export function parseStep(s: string): Step | null;
export function stepString(a: number, op: Op, b: number, ms: number): string;
export function replay(numbers: number[], target: number, steps: string[]): { best: number; distance: number; ms: number; steps: (Step & { value: number })[] };
export function roundPoints(distance: number, ms: number, seconds: number): number;
export function dailyTargetPoints(distance: number): number;
